INSERT INTO _virtual_seed VALUES
  ('virtuel.ga.01@profils-virtuels.yona.invalid', 'Prisca', 'Ondo', 'female', '1997-10-29', 'Gabon', 'Estuaire', 'Libreville', 'Souriante et attentionnée, j''aime la cuisine et la louange. J''enseigne à l''école du dimanche. J''attends un homme de foi, doux et responsable.', ARRAY['Louange', 'Cuisine']::text[], 'Adventiste', 'Plusieurs fois par semaine', 'Matin et soir', 'Au centre de ma vie', 'Relation sérieuse', 'male', 20, 38),
  ('virtuel.ga.02@profils-virtuels.yona.invalid', 'Steeve', 'Mintsa', 'male', '2000-04-03', 'Gabon', 'Ogooué-Maritime', 'Port-Gentil', 'Dynamique et fidèle en amitié, je consacre mon temps libre à la louange. La prière rythme mes journées. Je cherche une relation sérieuse, en vue du mariage.', ARRAY['Nature', 'Louange', 'Voyages']::text[], 'Adventiste', 'Plusieurs fois par semaine', 'Plusieurs fois par semaine', 'Très importante', 'Mariage', 'female', 18, 35),
  ('virtuel.ga.03@profils-virtuels.yona.invalid', 'Rachel', 'Obiang', 'female', '1986-04-18', 'Gabon', 'Haut-Ogooué', 'Franceville', 'Calme et joyeuse, je partage mon temps entre mon travail et le cinéma. J''enseigne à l''école du dimanche. J''aimerais rencontrer un homme qui place Dieu au centre de sa vie.', ARRAY['Voyages', 'Musique', 'Cinéma', 'Mode']::text[], 'Catholique', 'Chaque semaine', 'Matin et soir', 'Essentielle', 'Mariage', 'male', 31, 49),
  ('virtuel.ga.04@profils-virtuels.yona.invalid', 'Brice', 'Bivigou', 'male', '1979-03-27', 'Gabon', 'Woleu-Ntem', 'Oyem', 'Posé mais déterminé, j''aime les voyages, le cinéma et les longues discussions. Je joue dans le groupe de louange de mon église. Prêt à bâtir une famille fondée sur l''amour et la foi.', ARRAY['Lecture', 'Voyages', 'Cinéma']::text[], 'Protestante (Église évangélique du Gabon)', 'Chaque semaine', 'Plusieurs fois par semaine', 'Essentielle', 'Mariage', 'female', 38, 56),
  ('virtuel.ga.05@profils-virtuels.yona.invalid', 'Murielle', 'Nzé', 'female', '2000-07-14', 'Gabon', 'Haut-Ogooué', 'Moanda', 'Je suis une femme simple, passionnée par la mode et la cuisine. La prière rythme mes journées. J''attends un homme de foi, doux et responsable.', ARRAY['Cuisine', 'Nature', 'Mode', 'Bénévolat']::text[], 'Pentecôtiste', 'Chaque semaine', 'Plusieurs fois par semaine', 'Très importante', 'Relation sérieuse', 'male', 18, 35),
  ('virtuel.ga.06@profils-virtuels.yona.invalid', 'Wilfried', 'Moussavou', 'male', '1983-01-30', 'Gabon', 'Ngounié', 'Mouila', 'Calme et joyeux, je partage mon temps entre mon travail et la lecture. La prière rythme mes journées. Prêt à bâtir une famille fondée sur l''amour et la foi.', ARRAY['Louange', 'Lecture']::text[], 'Protestante (Église évangélique du Gabon)', 'Plusieurs fois par semaine', 'Tous les jours', 'Essentielle', 'Faire connaissance d''abord', 'female', 34, 52),
  ('virtuel.ga.07@profils-virtuels.yona.invalid', 'Vanessa', 'Nzamba', 'female', '1992-05-13', 'Gabon', 'Moyen-Ogooué', 'Lambaréné', 'Fille de Dieu avant tout, je trouve ma joie dans la mode et la danse. Je participe à un groupe de prière chaque semaine. Je crois au mariage, à la fidélité et au respect.', ARRAY['Mode', 'Danse']::text[], 'Protestante (Église évangélique du Gabon)', 'Chaque semaine', 'Matin et soir', 'Très importante', 'Mariage', 'male', 25, 43),
  ('virtuel.ga.08@profils-virtuels.yona.invalid', 'Arnaud', 'Mapangou', 'male', '2001-03-27', 'Gabon', 'Nyanga', 'Tchibanga', 'Calme et joyeux, je partage mon temps entre mon travail et la lecture. J''aide à l''organisation des sorties de l''église. Prêt à bâtir une famille fondée sur l''amour et la foi.', ARRAY['Lecture', 'Cinéma']::text[], 'Protestante (Église évangélique du Gabon)', 'Chaque semaine', 'Plusieurs fois par semaine', 'Au centre de ma vie', 'Relation sérieuse', 'female', 18, 34),
  ('virtuel.ga.09@profils-virtuels.yona.invalid', 'Ursule', 'Ekomi', 'female', '2001-12-03', 'Gabon', 'Ogooué-Lolo', 'Koulamoutou', 'Calme et joyeuse, je partage mon temps entre mon travail et les voyages. Je suis engagée dans le groupe de jeunes de ma paroisse. Prête à bâtir une famille fondée sur l''amour et la foi.', ARRAY['Nature', 'Voyages', 'Cuisine']::text[], 'Adventiste', 'Deux à trois fois par mois', 'Tous les jours', 'Au centre de ma vie', 'Mariage', 'male', 18, 34),
  ('virtuel.ga.10@profils-virtuels.yona.invalid', 'Landry', 'Mba', 'male', '1999-08-29', 'Gabon', 'Ogooué-Ivindo', 'Makokou', 'Chaque journée est un cadeau de Dieu : je la remplis de photographie et de voyages. Je sers à l''accueil de mon église le dimanche. Prêt à bâtir une famille fondée sur l''amour et la foi.', ARRAY['Photographie', 'Cuisine', 'Lecture', 'Voyages']::text[], 'Catholique', 'Deux à trois fois par mois', 'Matin et soir', 'Très importante', 'Faire connaissance d''abord', 'female', 18, 36),
  ('virtuel.ga.11@profils-virtuels.yona.invalid', 'Larissa', 'Ndong', 'female', '1989-01-21', 'Gabon', 'Estuaire', 'Ntoum', 'Douce mais déterminée, j''aime la cuisine, la photographie et les longues discussions. Le Psaume 23 m''accompagne depuis toujours. Je souhaite rencontrer un homme sincère pour construire un foyer béni.', ARRAY['Photographie', 'Cuisine']::text[], 'Catholique', 'Deux à trois fois par mois', 'Tous les jours', 'Très importante', 'Relation sérieuse', 'male', 28, 46),
  ('virtuel.ga.12@profils-virtuels.yona.invalid', 'Junior', 'Ella', 'male', '1995-02-19', 'Gabon', 'Estuaire', 'Libreville', 'Chaque journée est un cadeau de Dieu : je la remplis de cuisine et de sport. Ma foi guide chacune de mes décisions. Je crois au mariage, à la fidélité et au respect.', ARRAY['Sport', 'Danse', 'Cuisine', 'Photographie']::text[], 'Protestante (Église évangélique du Gabon)', 'Chaque semaine', 'Plusieurs fois par semaine', 'Très importante', 'Relation sérieuse', 'female', 22, 40),
  ('virtuel.ga.13@profils-virtuels.yona.invalid', 'Dorcas', 'Nguema', 'female', '2002-04-12', 'Gabon', 'Ogooué-Maritime', 'Port-Gentil', 'Chaque journée est un cadeau de Dieu : je la remplis de mode et de musique. Je participe à un groupe de prière chaque semaine. Je cherche une relation sérieuse, en vue du mariage.', ARRAY['Mode', 'Musique']::text[], 'Évangélique', 'Plusieurs fois par semaine', 'Matin et soir', 'Au centre de ma vie', 'Relation sérieuse', 'male', 18, 33),
  ('virtuel.ga.14@profils-virtuels.yona.invalid', 'Fabrice', 'Ognane', 'male', '1983-11-04', 'Gabon', 'Haut-Ogooué', 'Franceville', 'Chaque journée est un cadeau de Dieu : je la remplis de lecture et de photographie. Le Psaume 23 m''accompagne depuis toujours. Je crois au mariage, à la fidélité et au respect.', ARRAY['Photographie', 'Lecture']::text[], 'Catholique', 'Plusieurs fois par semaine', 'Plusieurs fois par semaine', 'Très importante', 'Relation sérieuse', 'female', 34, 52),
  ('virtuel.ga.15@profils-virtuels.yona.invalid', 'Christelle', 'Bouanga', 'female', '1993-01-31', 'Gabon', 'Woleu-Ntem', 'Oyem', 'Fille de Dieu avant tout, je trouve ma joie dans la musique et la photographie. Je participe à un groupe de prière chaque semaine. Prête à bâtir une famille fondée sur l''amour et la foi.', ARRAY['Musique', 'Photographie']::text[], 'Catholique', 'Plusieurs fois par semaine', 'Tous les jours', 'Essentielle', 'Mariage', 'male', 24, 42),
